import{_ as r,l as i,o as e,c as n,v as t,p as s,x as o,d as h,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"均光器与复眼","description":"","frontmatter":{"title":"均光器与复眼","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/homogenizer-fly-eye.md","filePath":"litho/homogenizer-fly-eye.md","lastUpdated":1789023840000}'),c={name:"litho/homogenizer-fly-eye.md"};function f(E,a,_,m,u,A){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="均光器与复眼" tabindex="-1">均光器与复眼 <a class="header-anchor" href="#均光器与复眼" aria-label="Permalink to &quot;均光器与复眼&quot;">​</a></h1><div class="epigraph"><p>激光近场并不均匀。复眼把光束切成子孔径再叠到光瞳上，均匀的是照明，不是把相干性抹成零。</p><footer>—— 对照照明均光 / fly&#39;s-eye integrator；[部分相干](/litho/partial-coherence)</footer></div><p><a href="/litho/laser-gas-lifetime">上一课</a>停在激光出口。缺口是：出口光束有热点和椭圆，不能直接打掩模。本课钉均光器与复眼，接到 <a href="/litho/off-axis-illumination">离轴照明</a>，不重做 σ。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>未均光的照明会把激光近场印到掩模上，CD 随狭缝位置变，像一台坏了的剂量机。均光要把空间均匀性做到百分比级，同时形成可调光瞳（环、偶极）。把均匀性写成「激光稳了就匀」，忽略积分器。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>复眼（fly&#39;s-eye）：阵列透镜把入射切成许多通道，在后续光瞳面重叠。光棒（rod）积分是另一条路。下游可变光瞳（<a href="/litho/flexray-pupil">FlexRay</a>）在已均光的场上整形。设计同时管：场均匀、光瞳填充、透过率。</p>',7)),(e(),s(p,null,{default:o(()=>[d(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAS%5B%22%E6%BF%80%E5%85%89%E8%BF%91%E5%9C%BA%22%5D%20--%3E%20FE%5B%22%E5%A4%8D%E7%9C%BC%E5%88%87%E5%88%86%22%5D%0A%20%20FE%20--%3E%20PUP%5B%22%E5%85%89%E7%9E%B3%E5%8F%A0%E5%8A%A0%22%5D%0A%20%20PUP%20--%3E%20MASK%5B%22%E6%8E%A9%E6%A8%A1%E9%9D%A2%E5%9D%87%E5%8C%80%E7%85%A7%E6%98%8E%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">通道数太少，均匀性有残纹；太多，透过率与对准公差变差。斑纹平均也依赖通道数与脉冲数。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>每条通道带一部分空间相干结构。重叠后强度均匀，互相干不完全消失，所以 σ 与光瞳形状仍由后续光阑定义。这是 <a href="/litho/temporal-spatial-coherence">空间相干</a> 在硬件上的实现，不是新的波动方程。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课 REMA 刀片切的是已均光的场，不是激光腔。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>复眼把不均匀激光叠成均匀掩模照明，并预备光瞳。</li><li>均匀性与部分相干是两件事，不要互相替代。</li><li>出处：照明积分器通识；部分相干课。</li></ul>',7))])}const T=r(c,[["render",f]]);export{x as __pageData,T as default};
